    75→    };
    76→
    77→abstract class AbstractBlockInput<F extends ForkName = ForkName, TData extends DAData = DAData>
    78→  implements IBlockInput<F, TData>
    79→{
    80→  abstract type: DAType;
    81→  daOutOfRange: boolean;
    82→  timeCreatedSec: number;
    83→
    84→  forkName: ForkName;
    85→  slot: Slot;
    86→  blockRootHex: string;
    87→  parentRootHex: string;
    88→
    89→  abstract state: BlockInputState<F>;
    90→
    91→  protected blockPromise = createPromise<SignedBeaconBlock<F>>();
    92→  protected dataPromise = createPromise<TData>();
    93→
    94→  constructor(init: BlockInputInit) {
    95→    this.daOutOfRange = init.daOutOfRange;
    96→    this.timeCreatedSec = init.timeCreated;
    97→    this.forkName = init.forkName;
    98→    this.slot = init.slot;
    99→    this.blockRootHex = init.blockRootHex;
   100→    this.parentRootHex = init.parentRootHex;
   101→  }
   102→
   103→  abstract addBlock(props: AddBlock<F>): void;
   104→
   105→  hasBlock(): boolean {
   106→    return this.state.hasBlock;
   107→  }
   108→
   109→  getBlock(): SignedBeaconBlock<F> {
   110→    if (!this.state.hasBlock) {
   111→      throw new BlockInputError(
   112→        {
   113→          code: BlockInputErrorCode.MISSING_BLOCK,
   114→          blockRoot: this.blockRootHex,
   115→        },
   116→        "Cannot getBlock from BlockInput without a block"
   117→      );
   118→    }
   119→    return this.state.block;
   120→  }
   121→
   122→  getBlockSource(): SourceMeta {
   123→    if (!this.state.hasBlock) {
   124→      throw new BlockInputError(
   125→        {
   126→          code: BlockInputErrorCode.MISSING_BLOCK,
   127→          blockRoot: this.blockRootHex,
   128→        },
   129→        "Cannot getBlockSource from BlockInput without a block"
   130→      );
   131→    }
   132→    return this.state.source;
   133→  }
   134→
   135→  hasAllData(): boolean {
   136→    return this.state.hasAllData;
   137→  }
   138→
   139→  hasBlockAndAllData(): boolean {
   140→    return this.state.hasBlock && this.state.hasAllData;
   141→  }
   142→
   143→  getLogMeta(): LogMetaBasic {
   144→    return {
   145→      slot: this.slot,
   146→      blockRoot: prettyBytes(this.blockRootHex),
   147→      timeCreatedSec: this.timeCreatedSec,
   148→    };
   149→  }
   150→
   151→  getTimeComplete(): number {
   152→    if (!this.state.hasBlock || !this.state.hasAllData) {
   153→      throw new BlockInputError(
   154→        {
   155→          code: BlockInputErrorCode.MISSING_TIME_COMPLETE,
   156→          blockRoot: this.blockRootHex,
   157→        },
   158→        "Cannot getTimeComplete from BlockInput without a block and data"
   159→      );
   160→    }
   161→    return this.state.timeCompleteSec;
   162→  }
   163→
   164→  waitForBlock(timeout: number, signal?: AbortSignal): Promise<SignedBeaconBlock<F>> {
   165→    if (!this.state.hasBlock) {
   166→      return withTimeout(() => this.blockPromise.promise, timeout, signal);
   167→    }
   168→    return Promise.resolve(this.state.block);
   169→  }
   170→  waitForAllData(timeout: number, signal?: AbortSignal): Promise<TData> {
   171→    return withTimeout(() => this.dataPromise.promise, timeout, signal);
   172→  }
   173→
   174→  async waitForBlockAndAllData(timeout: number, signal?: AbortSignal): Promise<this> {
   175→    if (!this.state.hasBlock || !this.state.hasAllData) {
   176→      await withTimeout(() => Promise.all([this.blockPromise.promise, this.dataPromise.promise]), timeout, signal);
   177→    }
   178→    return this;
   179→  }
   180→}
   181→
   182→// Pre-DA
   183→
   184→type BlockInputPreDataState = {
   185→  hasBlock: true;
   186→  hasAllData: true;
   187→  block: SignedBeaconBlock<ForkPreDeneb>;
   188→  source: SourceMeta;
   189→  timeCompleteSec: number;
   190→};
   191→
   192→/**
   193→ * Pre-DA, BlockInput only has a single state.
   194→ * - the block simply exists
   195→ */
   196→export class BlockInputPreData extends AbstractBlockInput<ForkPreDeneb, null> {
   197→  type = DAType.PreData as const;
   198→
   199→  state: BlockInputPreDataState;
   200→
   201→  private constructor(init: BlockInputInit, state: BlockInputPreDataState) {
   202→    super(init);
   203→    this.state = state;
   204→    this.dataPromise.resolve(null);
   205→    this.blockPromise.resolve(state.block);
   206→  }
   207→
   208→  static createFromBlock(props: AddBlock & CreateBlockInputMeta): BlockInputPreData {
   209→    const init: BlockInputInit = {
   210→      daOutOfRange: props.daOutOfRange,
   211→      timeCreated: props.seenTimestampSec,
   212→      forkName: props.forkName,
   213→      slot: props.block.message.slot,
   214→      blockRootHex: props.blockRootHex,
   215→      parentRootHex: toRootHex(props.block.message.parentRoot),
   216→    };
   217→    const state: BlockInputPreDataState = {
   218→      hasBlock: true,
   219→      hasAllData: true,
   220→      block: props.block,
   221→      source: {
   222→        source: props.source,
   223→        seenTimestampSec: props.seenTimestampSec,
   224→        peerIdStr: props.peerIdStr,
   225→      },
   226→      timeCompleteSec: props.seenTimestampSec,
   227→    };
   228→    return new BlockInputPreData(init, state);
   229→  }
   230→
   231→  addBlock(_: AddBlock, opts = {throwOnDuplicateAdd: true}): void {
   232→    if (opts.throwOnDuplicateAdd) {
   233→      throw new BlockInputError(
   234→        {
   235→          code: BlockInputErrorCode.INVALID_CONSTRUCTION,
   236→          blockRoot: this.blockRootHex,
   237→        },
   238→        "Cannot addBlock to BlockInputPreData"
   239→      );
   240→    }
   241→  }
   242→}
   243→
   244→// Blobs DA
   245→
   246→export type ForkBlobsDA = ForkName.deneb | ForkName.electra;
   247→
   248→type BlockInputBlobsState =
   249→  | {
   250→      hasBlock: true;
   251→      hasAllData: true;
   252→      versionedHashes: VersionedHashes;
   253→      block: SignedBeaconBlock<ForkBlobsDA>;
   254→      source: SourceMeta;
   255→      timeCompleteSec: number;
   256→    }
   257→  | {
   258→      hasBlock: true;
   259→      hasAllData: false;
   260→      versionedHashes: VersionedHashes;
   261→      block: SignedBeaconBlock<ForkBlobsDA>;
   262→      source: SourceMeta;
   263→    }
   264→  | {
   265→      hasBlock: false;
   266→      hasAllData: false;
   267→    };
   268→
   269→/**
   270→ * With blobs, BlockInput has several states:
   271→ * - The block is seen and all blobs are seen
   272→ * - The block is seen and all blobs are not yet seen
   273→ * - The block is yet not seen and its unknown if all blobs are seen
   274→ */
   275→export class BlockInputBlobs extends AbstractBlockInput<ForkBlobsDA, deneb.BlobSidecars> {
   276→  type = DAType.Blobs as const;
   277→
   278→  state: BlockInputBlobsState;
   279→  private blobsCache = new Map<BlobIndex, BlobWithSource>();
   280→
   281→  private constructor(init: BlockInputInit, state: BlockInputBlobsState) {
   282→    super(init);
   283→    this.state = state;
   284→  }
   285→
   286→  static createFromBlock(props: AddBlock<ForkBlobsDA> & CreateBlockInputMeta): BlockInputBlobs {
   287→    const hasAllData = props.daOutOfRange || props.block.message.body.blobKzgCommitments.length === 0;
   288→
   289→    const state = {
   290→      hasBlock: true,
   291→      hasAllData,
   292→      versionedHashes: props.block.message.body.blobKzgCommitments.map(kzgCommitmentToVersionedHash),
   293→      block: props.block,
   294→      source: {
   295→        source: props.source,
   296→        seenTimestampSec: props.seenTimestampSec,
   297→        peerIdStr: props.peerIdStr,
   298→      },
   299→      timeCompleteSec: hasAllData ? props.seenTimestampSec : undefined,
   300→    } as BlockInputBlobsState;
   301→    const init: BlockInputInit = {
   302→      daOutOfRange: props.daOutOfRange,
   303→      timeCreated: props.seenTimestampSec,
   304→      forkName: props.forkName,
   305→      slot: props.block.message.slot,
   306→      blockRootHex: props.blockRootHex,
   307→      parentRootHex: toRootHex(props.block.message.parentRoot),
   308→    };
   309→    const blockInput = new BlockInputBlobs(init, state);
   310→    blockInput.blockPromise.resolve(props.block);
   311→    if (hasAllData) {
   312→      blockInput.dataPromise.resolve([]);
   313→    }
   314→    return blockInput;
   315→  }
   316→
   317→  static createFromBlob(props: AddBlob & CreateBlockInputMeta): BlockInputBlobs {
   318→    const state: BlockInputBlobsState = {
   319→      hasBlock: false,
   320→      hasAllData: false,
   321→    };
   322→    const init: BlockInputInit = {
   323→      daOutOfRange: props.daOutOfRange,
   324→      timeCreated: props.seenTimestampSec,
   325→      forkName: props.forkName,
   326→      blockRootHex: props.blockRootHex,
   327→      parentRootHex: toRootHex(props.blobSidecar.signedBlockHeader.message.parentRoot),
   328→      slot: props.blobSidecar.signedBlockHeader.message.slot,
   329→    };
   330→    const blockInput = new BlockInputBlobs(init, state);
   331→    blockInput.blobsCache.set(props.blobSidecar.index, {
   332→      blobSidecar: props.blobSidecar,
   333→      source: props.source,
   334→      seenTimestampSec: props.seenTimestampSec,
   335→      peerIdStr: props.peerIdStr,
   336→    });
   337→    return blockInput;
   338→  }
   339→
   340→  getLogMeta(): LogMetaBlobs {
   341→    return {
   342→      slot: this.slot,
   343→      blockRoot: prettyBytes(this.blockRootHex),
   344→      timeCreatedSec: this.timeCreatedSec,
   345→      expectedBlobs: this.state.hasBlock ? this.state.block.message.body.blobKzgCommitments.length : "unknown",
   346→      receivedBlobs: this.blobsCache.size,
   347→    };
   348→  }
   349→
   350→  addBlock(
   351→    {blockRootHex, block, source, seenTimestampSec, peerIdStr}: AddBlock<ForkBlobsDA>,
   352→    opts = {throwOnDuplicateAdd: true}
   353→  ): void {
   354→    // this check suffices for checking slot, parentRoot, and forkName
   355→    if (blockRootHex !== this.blockRootHex) {
   356→      throw new BlockInputError(
   357→        {
   358→          code: BlockInputErrorCode.MISMATCHED_ROOT_HEX,
   359→          blockInputRoot: this.blockRootHex,
   360→          mismatchedRoot: blockRootHex,
   361→          source,
   362→          peerId: `${peerIdStr}`,
   363→        },
   364→        "addBlock blockRootHex does not match BlockInput.blockRootHex"
   365→      );
   366→    }
   367→
   368→    if (!opts.throwOnDuplicateAdd) {
   369→      return;
   370→    }
   371→
   372→    if (this.state.hasBlock) {
   373→      throw new BlockInputError(
   374→        {
   375→          code: BlockInputErrorCode.INVALID_CONSTRUCTION,
   376→          blockRoot: this.blockRootHex,
   377→        },
   378→        "Cannot addBlock to BlockInputBlobs after it already has a block"
   379→      );
   380→    }
   381→
   382→    for (const {blobSidecar} of this.blobsCache.values()) {
   383→      if (!blockAndBlobArePaired(block, blobSidecar)) {
   384→        this.blobsCache.delete(blobSidecar.index);
   385→        // TODO: (@matthewkeil) spec says to ignore invalid blobs but should we downscore the peer maybe?
   386→        // this.logger?.error(`Removing blobIndex=${blobSidecar.index} from BlockInput`, {}, err);
   387→      }
   388→    }
   389→
   390→    const hasAllData = this.blobsCache.size === block.message.body.blobKzgCommitments.length;
   391→
   392→    this.state = {
   393→      ...this.state,
   394→      hasBlock: true,
   395→      hasAllData,
   396→      block,
   397→      versionedHashes: block.message.body.blobKzgCommitments.map(kzgCommitmentToVersionedHash),
   398→      source: {
   399→        source,
   400→        seenTimestampSec,
   401→        peerIdStr,
   402→      },
   403→      timeCompleteSec: hasAllData ? seenTimestampSec : undefined,
   404→    } as BlockInputBlobsState;
   405→    this.blockPromise.resolve(block);
   406→    if (hasAllData) {
   407→      this.dataPromise.resolve(this.getBlobs());
   408→    }
   409→  }
   410→
   411→  hasBlob(blobIndex: BlobIndex): boolean {
   412→    return this.blobsCache.has(blobIndex);
   413→  }
   414→
   415→  addBlob(
   416→    {blockRootHex, blobSidecar, source, peerIdStr, seenTimestampSec}: AddBlob,
   417→    opts = {throwOnDuplicateAdd: true}
   418→  ): void {
   419→    // this check suffices for checking slot, parentRoot, and forkName
   420→    if (blockRootHex !== this.blockRootHex) {
   421→      throw new BlockInputError(
   422→        {
   423→          code: BlockInputErrorCode.MISMATCHED_ROOT_HEX,
   424→          blockInputRoot: this.blockRootHex,
   425→          mismatchedRoot: blockRootHex,
   426→          source: source,
   427→          peerId: `${peerIdStr}`,
   428→        },
   429→        "Blob BeaconBlockHeader blockRootHex does not match BlockInput.blockRootHex"
   430→      );
   431→    }
   432→
   433→    const isDuplicate = this.blobsCache.has(blobSidecar.index);
   434→    if (isDuplicate && opts.throwOnDuplicateAdd) {
   435→      throw new BlockInputError(
   436→        {
   437→          code: BlockInputErrorCode.INVALID_CONSTRUCTION,
   438→          blockRoot: this.blockRootHex,
   439→        },
   440→        "Cannot addBlob to BlockInputBlobs with duplicate blobIndex"
   441→      );
   442→    }
   443→
   444→    if (this.state.hasBlock) {
   445→      assertBlockAndBlobArePaired(this.blockRootHex, this.state.block, blobSidecar);
   446→    }
   447→
   448→    if (isDuplicate) {
   449→      return;
   450→    }
   451→
   452→    this.blobsCache.set(blobSidecar.index, {blobSidecar, source, seenTimestampSec, peerIdStr});
   453→
   454→    if (this.state.hasBlock && this.blobsCache.size === this.state.block.message.body.blobKzgCommitments.length) {
   455→      this.state = {
   456→        ...this.state,
   457→        hasAllData: true,
   458→        timeCompleteSec: seenTimestampSec,
   459→      };
   460→      this.dataPromise.resolve([...this.blobsCache.values()].map(({blobSidecar}) => blobSidecar));
   461→    }
   462→  }
   463→
   464→  getVersionedHashes(): VersionedHashes {
   465→    if (!this.state.hasBlock) {
   466→      throw new BlockInputError(
   467→        {
   468→          code: BlockInputErrorCode.INCOMPLETE_DATA,
   469→          ...this.getLogMeta(),
   470→        },
   471→        "Cannot get versioned hashes. Block is unknown"
   472→      );
   473→    }
   474→    return this.state.versionedHashes;
   475→  }
   476→
   477→  getMissingBlobMeta(): BlobMeta[] {
   478→    if (!this.state.hasBlock) {
   479→      throw new BlockInputError(
   480→        {
   481→          code: BlockInputErrorCode.INCOMPLETE_DATA,
   482→          ...this.getLogMeta(),
   483→        },
   484→        "Cannot get missing blobs. Block is unknown"
   485→      );
   486→    }
   487→    if (this.state.hasAllData) {
   488→      return [];
   489→    }
   490→
   491→    const blobMeta: BlobMeta[] = [];
   492→    const versionedHashes = this.state.versionedHashes;
   493→    for (let index = 0; index < versionedHashes.length; index++) {
   494→      if (!this.blobsCache.has(index)) {
   495→        blobMeta.push({
   496→          index,
   497→          blockRoot: fromHex(this.blockRootHex),
   498→          versionedHash: versionedHashes[index],
   499→        });
   500→      }
   501→    }
   502→    return blobMeta;
   503→  }
   504→
   505→  getAllBlobsWithSource(): BlobWithSource[] {
   506→    if (!this.state.hasAllData) {
   507→      throw new BlockInputError(
   508→        {
   509→          code: BlockInputErrorCode.INCOMPLETE_DATA,
   510→          ...this.getLogMeta(),
   511→        },
   512→        "Cannot get all blobs. DA status is not complete"
   513→      );
   514→    }
   515→    return [...this.blobsCache.values()];
   516→  }
   517→
   518→  getBlobs(): deneb.BlobSidecars {
   519→    return this.getAllBlobsWithSource().map(({blobSidecar}) => blobSidecar);
   520→  }
   521→}
   522→
   523→function blockAndBlobArePaired(block: SignedBeaconBlock<ForkBlobsDA>, blobSidecar: deneb.BlobSidecar): boolean {
   524→  const blockCommitment = block.message.body.blobKzgCommitments[blobSidecar.index];
   525→  if (!blockCommitment || !blobSidecar.kzgCommitment) {
   526→    return false;
   527→  }
   528→  return Buffer.compare(blockCommitment, blobSidecar.kzgCommitment) === 0;
   529→}
   530→
   531→function assertBlockAndBlobArePaired(
   532→  blockRootHex: string,
   533→  block: SignedBeaconBlock<ForkBlobsDA>,
   534→  blobSidecar: deneb.BlobSidecar
   535→): void {
   536→  if (!blockAndBlobArePaired(block, blobSidecar)) {
   537→    // TODO: (@matthewkeil) should this eject the bad blob instead? No way to tell if the blob or the block
   538→    //       has the invalid commitment. Guessing it would be the blob though because we match via block
   539→    //       hashTreeRoot and we do not take a hashTreeRoot of the BlobSidecar
   540→    throw new BlockInputError(
   541→      {
   542→        code: BlockInputErrorCode.MISMATCHED_KZG_COMMITMENT,
   543→        blockRoot: blockRootHex,
   544→        slot: block.message.slot,
   545→        sidecarIndex: blobSidecar.index,
   546→      },
   547→      "BlobSidecar commitment does not match block commitment"
   548→    );
   549→  }
   550→}
   551→
   552→// Columns DA
   553→
   554→export type ForkColumnsDA = ForkName.fulu;
   555→
   556→type BlockInputColumnsState =
   557→  | {
   558→      hasBlock: true;
   559→      hasAllData: true;
   560→      versionedHashes: VersionedHashes;
   561→      block: SignedBeaconBlock<ForkColumnsDA>;
   562→      source: SourceMeta;
   563→      timeCompleteSec: number;
   564→    }
   565→  | {
   566→      hasBlock: true;
   567→      hasAllData: false;
   568→      versionedHashes: VersionedHashes;
   569→      block: SignedBeaconBlock<ForkColumnsDA>;
   570→      source: SourceMeta;
   571→    }
   572→  | {
   573→      hasBlock: false;
   574→      hasAllData: true;
   575→      versionedHashes: VersionedHashes;
   576→    }
   577→  | {
   578→      hasBlock: false;
   579→      hasAllData: false;
   580→      versionedHashes: VersionedHashes;
   581→    };
   582→/**
   583→ * With columns, BlockInput has several states:
   584→ * - The block is seen and all required sampled columns are seen
   585→ * - The block is seen and all required sampled columns are not yet seen
   586→ * - The block is not yet seen and all required sampled columns are seen
   587→ * - The block is not yet seen and all required sampled columns are not yet seen
   588→ */
   589→export class BlockInputColumns extends AbstractBlockInput<ForkColumnsDA, fulu.DataColumnSidecars> {
   590→  type = DAType.Columns as const;
   591→
   592→  state: BlockInputColumnsState;
   593→
   594→  private columnsCache = new Map<ColumnIndex, ColumnWithSource>();
   595→  private readonly sampledColumns: ColumnIndex[];
   596→  private readonly custodyColumns: ColumnIndex[];
   597→
   598→  private constructor(
   599→    init: BlockInputInit,
   600→    state: BlockInputColumnsState,
   601→    sampledColumns: ColumnIndex[],
   602→    custodyColumns: ColumnIndex[]
   603→  ) {
   604→    super(init);
   605→    this.state = state;
   606→    this.sampledColumns = sampledColumns;
   607→    this.custodyColumns = custodyColumns;
   608→  }
   609→
   610→  get columnCount(): number {
   611→    return this.columnsCache.size;
   612→  }
   613→
   614→  static createFromBlock(
   615→    props: AddBlock<ForkColumnsDA> &
   616→      CreateBlockInputMeta & {sampledColumns: ColumnIndex[]; custodyColumns: ColumnIndex[]}
   617→  ): BlockInputColumns {
   618→    const hasAllData =
   619→      props.daOutOfRange ||
   620→      props.block.message.body.blobKzgCommitments.length === 0 ||
   621→      props.sampledColumns.length === 0;
   622→    const state = {
   623→      hasBlock: true,
   624→      hasAllData,
   625→      versionedHashes: props.block.message.body.blobKzgCommitments.map(kzgCommitmentToVersionedHash),
   626→      block: props.block,
   627→      source: {
   628→        source: props.source,
   629→        seenTimestampSec: props.seenTimestampSec,
   630→        peerIdStr: props.peerIdStr,
   631→      },
   632→      timeCreated: props.seenTimestampSec,
   633→      timeCompleteSec: hasAllData ? props.seenTimestampSec : undefined,
   634→    } as BlockInputColumnsState;
   635→    const init: BlockInputInit = {
   636→      daOutOfRange: props.daOutOfRange,
   637→      timeCreated: props.seenTimestampSec,
   638→      forkName: props.forkName,
   639→      blockRootHex: props.blockRootHex,
   640→      parentRootHex: toRootHex(props.block.message.parentRoot),
   641→      slot: props.block.message.slot,
   642→    };
   643→    const blockInput = new BlockInputColumns(init, state, props.sampledColumns, props.custodyColumns);
   644→
   645→    blockInput.blockPromise.resolve(props.block);
   646→    if (hasAllData) {
   647→      blockInput.dataPromise.resolve([]);
   648→    }
   649→    return blockInput;
   650→  }
   651→
   652→  static createFromColumn(
   653→    props: AddColumn & CreateBlockInputMeta & {sampledColumns: ColumnIndex[]; custodyColumns: ColumnIndex[]}
   654→  ): BlockInputColumns {
   655→    const hasAllData =
   656→      props.daOutOfRange || props.columnSidecar.kzgCommitments.length === 0 || props.sampledColumns.length === 0;
   657→    const state: BlockInputColumnsState = {
   658→      hasBlock: false,
   659→      hasAllData,
   660→      versionedHashes: props.columnSidecar.kzgCommitments.map(kzgCommitmentToVersionedHash),
   661→    };
   662→    const init: BlockInputInit = {
   663→      daOutOfRange: false,
   664→      timeCreated: props.seenTimestampSec,
   665→      forkName: props.forkName,
   666→      blockRootHex: props.blockRootHex,
   667→      parentRootHex: toRootHex(props.columnSidecar.signedBlockHeader.message.parentRoot),
   668→      slot: props.columnSidecar.signedBlockHeader.message.slot,
   669→    };
   670→    const blockInput = new BlockInputColumns(init, state, props.sampledColumns, props.custodyColumns);
   671→    if (hasAllData) {
   672→      blockInput.dataPromise.resolve([]);
   673→    }
   674→    return blockInput;
   675→  }
   676→
   677→  getLogMeta(): LogMetaColumns {
   678→    return {
   679→      slot: this.slot,
   680→      blockRoot: prettyBytes(this.blockRootHex),
   681→      timeCreatedSec: this.timeCreatedSec,
   682→      expectedColumns:
   683→        this.state.hasBlock && this.state.block.message.body.blobKzgCommitments.length === 0
   684→          ? 0
   685→          : this.sampledColumns.length,
   686→      receivedColumns: this.getSampledColumns().length,
   687→    };
   688→  }
   689→
